def slots_status_to_withdrawn_at(apps, schema_editor):
    """Availability is now computed: a CANCELLED slot becomes a withdrawn one (nothing was BOOKED yet)."""
    MentorSlot = apps.get_model('mentoring', 'MentorSlot')
    for slot in MentorSlot.objects.filter(status='CANCELLED'):
        slot.withdrawn_at = slot.updated_at
        slot.save(update_fields=['withdrawn_at'])


def slots_withdrawn_at_to_status(apps, schema_editor):
    MentorSlot = apps.get_model('mentoring', 'MentorSlot')
    MentorSlot.objects.filter(withdrawn_at__isnull=False).update(status='CANCELLED')


